import { mountAdPlacement } from './ads.js';
import { buildMoveSession,recordMoveChoice,mistakeExplanation } from './battles.js';
import { matchupKey } from './matchup.js';
import { createSoundPlayer } from './sound.js';
import { moveExample } from './move-examples.js';
import { POKEMON,BUDDIES,pokemonTypes,pokemonForTypes,representative,byId,spriteUrl } from './pokemon.js';
import { TYPES,COLORS,ERAS,typesFor,effectiveness,dualEffectiveness,LABELS,multiplier,mnemonic,pairsFor,LESSONS } from './data.js';
import { STORAGE_KEY,freshState,mastered,due,recordAnswer,stats,lessonQuestions,buildSession,validateState,resetProgress,restoreProgress,validateResetBackup,courseStatus,studyPriorities,buildStudySession,recordChallenge,CHALLENGE_PASS,recentMistakes } from './progress.js';

const paths={volume:'m3 9 4 0 5-4v14l-5-4H3V9Zm12-1c3 2 3 6 0 8m3-11c5 4 5 10 0 14',mute:'m3 9 4 0 5-4v14l-5-4H3V9Zm13 0 5 6m0-6-5 6',restart:'M4 10a8 8 0 1 1 1 8M4 4v6h6',home:'M3 10 12 3l9 7v10H3V10Zm6 10v-7h6v7',book:'M12 5v15M3 4c4-1 7 0 9 2 2-2 5-3 9-2v15c-4-1-7 0-9 2-2-2-5-3-9-2V4Z',swords:'m4 3 15 15M3 4l3 6 4-4-6-3Zm14 14 4 4m-3-1 3-3M20 3 5 18m16-14-3 6-4-4 6-3ZM7 17l-4 4m1-3 3 3',grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',chart:'M4 20V4m0 16h17M8 16v-4m5 4V8m5 8V5',arrow:'M4 12h16m-6-6 6 6-6 6',chevron:'m9 5 7 7-7 7',check:'m5 12 4 4L19 6',spark:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5L12 3Z',clock:'M12 8v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',bolt:'m13 2-9 12h7l-1 8 10-13h-7l1-7Z',target:'M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0Zm-4 0a6 6 0 1 1-12 0 6 6 0 0 1 12 0Zm-6-2v4m-2-2h4',trophy:'M8 3h8v8a4 4 0 0 1-8 0V3Zm0 2H4v3a4 4 0 0 0 4 4m8-7h4v3a4 4 0 0 1-4 4m-4 3v6m-4 0h8',download:'M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4',upload:'M12 16V4m-5 5 5-5 5 5M4 17v4h16v-4',search:'M16 10a6 6 0 1 1-12 0 6 6 0 0 1 12 0Zm-1 5 6 6',heart:'M12 21 3 12C-2 6 6-1 12 6c6-7 14 0 9 6l-9 9Z',info:'M12 11v6m0-10v.1M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',close:'m6 6 12 12M6 18 18 6',leaf:'M20 3c-12-2-19 9-12 14s13-2 12-14ZM5 21 16 8',flame:'M12 2c2 6 8 8 8 14a8 8 0 0 1-16 0c0-3 2-5 4-7 0 4 2 5 3 4 2-2 2-6 1-11Z',drop:'M12 2C9 7 4 12 4 16a8 8 0 0 0 16 0c0-4-5-9-8-14Z',shield:'m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6l8-3Z',mountain:'m2 20 7-14 5 8 3-5 5 11H2Zm4-8 3 2 3-3',moon:'M20 16A9 9 0 0 1 8 4a9 9 0 1 0 12 12Z',sun:'M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0ZM12 1v3m0 16v3M1 12h3m16 0h3M4 4l2 2m12 12 2 2M20 4l-2 2M6 18l-2 2',wing:'M3 19c0-12 12-16 18-16-1 8-6 17-18 16Zm1-1L17 7M8 10l1 4m4-7 1 3',bug:'M8 8h8v8a4 4 0 0 1-8 0V8ZM9 8V5h6v3m-7 3H4m12 0h4m-12 4H3m13 0h5m-12 5-3 2m10-2 3 2M9 5 7 2m8 3 2-3',ghost:'M4 21V10a8 8 0 0 1 16 0v11l-4-3-4 3-4-3-4 3ZM9 10v2m6-2v2',snow:'M12 2v20M3 7l18 10M3 17 21 7M9 4l3 3 3-3M9 20l3-3 3 3',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12Zm13 0a3 3 0 1 1-6 0 3 3 0 0 1 6 0',diamond:'m12 2 10 10-10 10L2 12 12 2Z',flower:'M12 9c-7-12-14 2-3 3-12 7 2 14 3 3 7 12 14-2 3-3 12-7-2-14-3-3Z'};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.spark}"/></svg>`;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const typeIcon=t=>{const p=byId(moveExample(t,state.era)?.pokemonId)||representative(t,state.era);return `<span class="type-sprite-frame" aria-hidden="true"><img class="type-sprite" src="${spriteUrl(p,false)}" alt="" width="48" height="48" draggable="false"></span>`;};
const badge=(t,big=false)=>`<span class="type-badge ${big?'large':''}" style="--type:${COLORS[t]}">${typeIcon(t)}${t}</span>`;
const orb=t=>`<span class="type-orb" style="--type:${COLORS[t]}">${typeIcon(t)}</span>`;

const updateAdPlacement=mountAdPlacement(document,window);
const motionPreference=matchMedia('(prefers-reduced-motion: reduce)');
let settings={buddy:25,motion:true,sound:true,volume:25,battleEffects:true};
try { const saved=JSON.parse(localStorage.getItem('type-dojo-settings-v1')); if(saved){settings.buddy=BUDDIES.includes(saved.buddy)?saved.buddy:25;settings.motion=saved.motion!==false;settings.sound=saved.sound!==false;settings.battleEffects=saved.battleEffects!==false;settings.volume=Number.isFinite(saved.volume)?Math.max(0,Math.min(100,saved.volume)):25;} } catch {}
const sounds=createSoundPlayer();
sounds.configure({enabled:settings.sound,volume:settings.volume,battleEffects:settings.battleEffects});
const soundOn=()=>settings.sound&&settings.volume>0;
const soundControl=()=>`<div class="sound-control-group"><button id="sound-toggle" class="sound-toggle" data-action="sound-toggle" aria-pressed="${soundOn()}" aria-label="${soundOn()?'Mute gentle sounds':'Enable gentle sounds'}">${icon(soundOn()?'volume':'mute')}<span>Sound ${soundOn()?'on':'off'}</span></button><button class="sound-settings-button" data-action="sound-settings" aria-label="Sound settings" title="Sound settings">${icon('chevron')}</button></div>`;
function refreshSoundControl(){const button=document.querySelector('#sound-toggle');if(button)button.parentElement.outerHTML=soundControl();}
const buddy=()=>byId(settings.buddy);
const animationEnabled=()=>settings.motion&&!motionPreference.matches;
function saveSettings(){try{localStorage.setItem('type-dojo-settings-v1',JSON.stringify(settings));}catch{toast('Your preferences apply for this visit; this browser could not save them.');}}
function sprite(p,cls='',alt=null){p=typeof p==='number'?byId(p):p;if(!p)return '';return `<img class="pokemon-sprite ${animationEnabled()?'animated':'still'} ${cls}" src="${spriteUrl(p,animationEnabled())}" width="96" height="96" alt="${esc(alt===null?p.name:alt)}" draggable="false">`;}
function buddyPicker(){return `<div class="buddy-picker"><span>CHOOSE YOUR STUDY BUDDY</span><div>${BUDDIES.map(id=>`<button class="buddy-choice ${settings.buddy===id?'chosen':''}" data-buddy="${id}" aria-label="Choose ${byId(id).name} as your study buddy" aria-pressed="${settings.buddy===id}">${sprite(id,'','')}<span>${byId(id).name}</span>${settings.buddy===id?icon('check'):''}</button>`).join('')}</div></div>`;}
function typeCast(types,cls=''){return `<div class="pokemon-cast ${cls}">${types.filter(t=>typesFor(state.era).includes(t)).map(t=>{const p=representative(t,state.era);return `<div class="cast-member" style="--type:${COLORS[t]}">${sprite(p,'','')}<span>${p.name}</span><div class="cast-types">${pokemonTypes(p,state.era).map(actual=>badge(actual)).join(' ')}</div></div>`;}).join('')}</div>`;}
function battleActor(types,attacking=false,pokemonId=null){const p=pokemonId?byId(pokemonId):attacking?(byId(moveExample(types[0],state.era)?.pokemonId)||representative(types[0],state.era)):pokemonForTypes(types,state.era);return `<div class="battle-actor ${attacking?'attacker':'defender'}" style="--type:${COLORS[types[0]]}"><span class="battle-platform"></span>${p?sprite(p,'',''):`<div class="target-dummy"><span class="dummy-ball"></span><div>${types.map(orb).join('')}</div></div>`}<span class="actor-name">${p?p.name:'Practice target'}</span></div>`;}
function typeSpotlight(type){const p=representative(type,state.era);return `<div class="pokemon-spotlight" style="--type:${COLORS[type]}"><div class="spotlight-sprite">${sprite(p,'','')}</div><div><span class="eyebrow">MEET THE TYPE</span><h3>${p.name}</h3><p>A familiar face for ${type}. ${pokemonTypes(p,state.era).length>1?'This Pokémon has two types—both matter in a real battle.':'A single-type example to make the matchup stick.'}</p><div>${pokemonTypes(p,state.era).map(t=>badge(t)).join(' ')}</div></div><span class="dex-number">#${String(p.id).padStart(3,'0')}</span></div>`;}

let storageOK=true,state=freshState();
try {const raw=localStorage.getItem(STORAGE_KEY); if(raw) state=validateState(JSON.parse(raw));} catch {storageOK=false;}
let view=['home','learn','practice','library','chart','progress'].includes(location.hash.slice(1))?location.hash.slice(1):'home';
let resetBackup=null;
try{const raw=localStorage.getItem('type-dojo-reset-backup-v1');if(raw)resetBackup=validateResetBackup(JSON.parse(raw));}catch{}
let session=null,lessonId=null,libraryType='Water',librarySearch='',libraryFilter='all';
const bucket=()=>state.eras[state.era];
function save(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state));storageOK=true;}catch{storageOK=false;toast('Your browser could not save progress. Export a backup to keep it.');}}
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('visible'),4500);}
function metric(label,value,sub,symbol){return `<div class="metric"><div class="metric-icon">${icon(symbol)}</div><div><span class="metric-label">${label}</span><div class="metric-number">${value}</div><span class="muted small">${sub}</span></div></div>`;}
function artwork(){return `<div class="hero-world"><div class="route-scene" role="img" aria-label="A pixel-art Pokémon training meadow with Bulbasaur, Charmander, Squirtle, Snorlax, and your study buddy ${buddy().name}"><span class="route-sign">${icon('leaf')} ROUTE 01 <small>THE TRAINING MEADOW</small></span><span class="field-pokemon field-bulbasaur">${sprite(1,'','')}</span><span class="field-pokemon field-charmander">${sprite(4,'','')}</span><span class="field-pokemon field-squirtle">${sprite(7,'','')}</span><span class="field-pokemon field-snorlax">${sprite(143,'','')}</span><span class="field-pokemon field-buddy">${sprite(buddy(),'','')}<span class="buddy-nameplate">${buddy().name} is cheering you on!</span></span><span class="scene-spark spark-one">✦</span><span class="scene-spark spark-two">✦</span><span class="scene-caption">NEW TRAINER? THIS IS YOUR STARTING TOWN.</span></div></div>`;}

function shell(content){const s=stats(bucket(),state.era);return `<aside class="sidebar"><a class="brand" href="#home" data-nav="home"><span class="brand-mark"><span></span></span><span>type<span class="brand-light">dojo</span><small>POKÉMON TRAINER HQ</small></span></a><div class="nav-label">YOUR TRAINING SPACE</div><nav aria-label="Main navigation">${[['home','home','Overview'],['learn','book','Ground Zero'],['practice','swords','Practice arena'],['library','grid','Type library'],['chart','target','Matchup chart'],['progress','chart','My progress']].map(([id,i,label])=>`<a href="#${id}" data-nav="${id}" class="nav-item ${view===id?'active':''}" ${view===id?'aria-current="page"':''}>${icon(i)}<span>${label}</span>${id==='practice'&&s.due?`<span class="nav-count">${s.due}</span>`:''}</a>`).join('')}</nav><div class="sidebar-bottom"><div class="trainer-card"><span class="avatar buddy-avatar">${sprite(buddy(),'','')}</span><div><b>${s.xp>=1500?'Type ace':s.xp>=500?'Rising trainer':'Fresh trainer'}</b><small>${s.xp} XP · ${ERAS[state.era].short}</small></div>${icon('spark')}</div><div class="buddy-dialogue"><b>${buddy().name} used Encouragement!</b><p>One matchup at a time.<br>You’ve got this, trainer.</p></div><span class="local-dot">Progress saved on this device</span></div></aside><div class="workspace"><header class="topbar"><span class="breadcrumb">Your dojo <span>/</span> ${({home:'Overview',learn:'Ground Zero',practice:'Practice arena',library:'Type library',chart:'Matchup chart',progress:'My progress'})[view]}</span><div class="topbar-right"><label class="era-label" for="era">GAME RULES</label><select id="era" aria-label="Game generation">${Object.entries(ERAS).map(([id,e])=>`<option value="${id}" ${state.era===id?'selected':''}>${e.name}</option>`).join('')}</select>${soundControl()}<button class="motion-control" data-action="motion" aria-label="${animationEnabled()?'Pause sprite animation':'Play sprite animation'}" title="${motionPreference.matches?'Animations follow your reduced-motion setting':animationEnabled()?'Pause sprite animation':'Play sprite animation'}" ${motionPreference.matches?'disabled':''}>${icon(animationEnabled()?'sun':'moon')}</button><span class="mini-avatar buddy-avatar">${sprite(buddy(),'','')}</span></div></header><main id="main" tabindex="-1">${!storageOK?'<div class="notice">Progress storage is unavailable or an old save could not be read. You can use Export backup in My progress to keep this session.</div>':''}${content}<footer><span>An unofficial Pokémon learning adventure. Sprites via PokéAPI. <a href="./about.html" target="_blank" rel="noopener">About &amp; contact</a> · <a href="./privacy.html" target="_blank" rel="noopener">Privacy</a></span><span>${ERAS[state.era].short} · Main-series type rules <button class="text-button" data-action="sources">Sources & scope ${icon('info')}</button></span></footer></main></div>`;}
function heading(kicker,title,description,extra=''){return `<div class="page-heading"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${description}</p></div>${extra}</div>`;}
function modeCard(id,symbol,title,description,tag=''){const partner=({attack:25,defense:143,immunity:94,dual:149,review:63,challenge:448})[id];return `<button class="mode-card" data-mode="${id}"><span class="mode-pokemon ${id}">${sprite(partner,'','')}</span><span class="mode-copy"><b>${title}</b><span>${description}</span></span>${tag?`<span class="pill">${tag}</span>`:icon('arrow')}</button>`;}
function home(){const s=stats(bucket(),state.era),course=courseStatus(bucket(),state.era),available=course.available,next=course.next,percent=Math.round(s.mastered/s.total*100);return `${heading('SMALL STEPS. SUPER EFFECTIVE RESULTS.',s.attempted?'Welcome back, trainer.':'Your adventure starts here.','Learn the matchups. Find your rhythm. Become the trainer you want to be.',`<span class="soft-pill">${icon('sun')} Your pace. Your journey.</span>`)}<section class="hero pokemon-hero"><div class="hero-copy"><span class="pill hero-tag">${icon('spark')} FROM ZERO TO TYPE HERO</span><h2>Your Pokémon journey.<br>Your <em>type advantage.</em></h2><p>Meet your study buddy, step into the tall grass, and learn the matchups that turn a new trainer into a Pokémon pro.</p><button class="primary" data-action="continue">${course.graduated?'Meet your Type Hero challenge':course.completed.length?'Continue your journey':'Start from Ground Zero'}${icon('arrow')}</button><span class="hero-note">${icon('clock')} Small lessons. Real Pokémon. Big “aha” moments.</span>${buddyPicker()}<div class="journey-controls"><button class="text-button" data-action="restart-journey">${icon('restart')} Restart journey</button>${resetBackup?'<button class="text-button" data-action="undo-reset">Undo last reset</button>':''}<span>${ERAS[state.era].short} · Saved on this device</span></div></div>${artwork()}</section><section class="metrics" aria-label="Training statistics">${metric('Matchups mastered',`${s.mastered}<span> / ${s.total}</span>`,'3 unaided answers + later recall','target')}${metric('Practice accuracy',s.attempted?`${s.accuracy}<span>%</span>`:'—',s.attempted?`${s.attempted} questions answered`:'Your first answer starts this','bolt')}${metric('Ready for review',s.due,'Missed or due for a refresh','clock')}${metric('Training days',bucket().days.length,'Every little session counts','leaf')}</section>${course.graduated?graduationCard():''}${studyGuide()}<div class="section-heading"><div><h2>Find your next aha moment</h2><p>A starting point for every kind of trainer.</p></div><button class="text-button" data-nav="practice">Explore the arena ${icon('arrow')}</button></div><div class="training-cards"><button class="training-card starter" data-nav="learn"><div class="card-top"><span class="mode-icon">${icon('leaf')}</span><span class="pill">BEGINNER FRIENDLY</span></div><div class="card-pokemon-scene starter-scene">${sprite(1,'','')}${sprite(4,'','')}${sprite(7,'','')}</div><h3>Ground Zero</h3><p>Never learned the types? Start with three familiar faces and build from there.</p><div class="card-bottom"><span>${course.completed.length} / ${available.length} lessons complete</span>${icon('arrow')}</div></button><button class="training-card" data-mode="attack"><div class="card-top"><span class="mode-icon pink">${icon('swords')}</span><span class="pill">BUILD YOUR INSTINCTS</span></div><div class="card-pokemon-scene battle-card-scene">${sprite(25,'','')}<span>VS</span>${sprite(130,'','')}</div><h3>Matchup practice</h3><p>Call the damage. Get a memory hook. Make the tricky matchups feel familiar.</p><div class="card-bottom"><span>10 questions · No time pressure</span>${icon('arrow')}</div></button><button class="training-card" data-mode="review"><div class="card-top"><span class="mode-icon gold">${icon('clock')}</span><span class="pill">MADE FOR YOU</span></div><div class="card-pokemon-scene review-scene">${sprite(63,'','')}<span class="memory-stars">✦ &nbsp; ✧</span></div><h3>Refresh & remember</h3><p>Turn “I always forget that one” into “I’ve got this.” Revisit what needs a little love.</p><div class="card-bottom"><span>${s.due?s.due+' matchups ready':'Your review queue starts as you practice'}</span>${icon('arrow')}</div></button></div><div class="home-bottom"><section class="memory-card"><span class="eyebrow">${icon('spark')} MAKE IT STICK</span><div class="memory-sprite-duel">${sprite(7,'','')}<span class="water-splash">${icon('drop')}${icon('arrow')}</span>${sprite(4,'','')}</div><div class="memory-inner"><div>${badge('Water')}${icon('arrow')}${badge('Fire')}</div><blockquote>“Water puts out fire.”</blockquote><p>That’s why a Water-type move is super effective against a Fire-type Pokémon. A simple picture beats a wall of numbers.</p></div><button class="text-button" data-nav="library">Explore memory hooks ${icon('arrow')}</button></section><section class="journey-card"><div class="section-heading"><h3>Your path to type hero</h3><span class="purple-text">${percent}% mastered</span></div><div class="progress-track"><span style="width:${percent}%"></span></div><div class="journey-step"><span class="step-number">1</span><div><b>Build your foundation</b><small>${course.graduated?'All Ground Zero chapters complete':'Next up: '+next.title}</small></div>${icon('chevron')}</div><div class="journey-step"><span class="step-number muted-step">2</span><div><b>Make it second nature</b><small>Practice every advantage, resistance & immunity</small></div></div><div class="journey-step"><span class="step-number muted-step">3</span><div><b>Think like a type hero</b><small>Master dual types & take the final challenge</small></div></div></section></div>`;}

function studyGuide(){
  const priorities=studyPriorities(bucket(),state.era),started=Object.values(bucket().records).some(r=>r.attempts>0);
  const tricky=priorities.some(p=>p.misses||p.hints);
  const title=priorities.length?(tricky?(priorities.length===3?'Your three trickiest types':'Your trickiest types'):'Keep these types fresh'):(started?'Your instincts are in good shape':'Let’s find your tricky types');
  return `<section class="study-plan" aria-labelledby="study-plan-title"><div class="study-plan-heading"><div><span class="eyebrow">A LITTLE FOCUS GOES A LONG WAY · ${ERAS[state.era].short}</span><h2 id="study-plan-title">${title}</h2><p>${priorities.length?'These types attack or defend in the matchups that need your attention.':'A short session helps '+(started?'keep your instincts sharp.':'build your first personal study plan. Start with Fire, Water, and Grass.')}</p></div><span class="study-time">${icon('clock')} 6 questions · About 2 minutes</span></div>${priorities.length?`<div class="priority-grid">${priorities.map((p,i)=>`<article class="priority-card" style="--type:${COLORS[p.type]}"><span class="priority-rank">${i+1}</span>${sprite(representative(p.type,state.era),'priority-pokemon','')}<div>${badge(p.type,true)}<p>${p.reason==='misses'?p.misses+' '+(p.misses===1?'miss':'misses')+' on matchups still being learned':p.reason==='hints'?p.hints+' '+(p.hints===1?'hint':'hints')+' used while learning':p.reason==='review'?p.review+' '+(p.review===1?'matchup':'matchups')+' ready for review':p.learning+' '+(p.learning===1?'matchup':'matchups')+' building confidence'}</p></div></article>`).join('')}</div>`:`<div class="study-empty">${sprite(buddy(),'','')}<p>${started?'Your mastered matchups are up to date. A mixed practice round will keep you on your toes.':'A few answers will reveal where you need help. This space updates as you practice.'}</p></div>`}${recentMistakes(bucket(),state.era).length?`<div class="specific-mistakes"><b>Matchups to untangle</b>${recentMistakes(bucket(),state.era).map(q=>`<p>${esc(q.a)} → ${esc(q.ds.join(' / '))}<small>${q.record.lastMistake.kind==='move'?'A move with a better advantage was available':'You chose '+multiplier(q.record.lastMistake.selected)+' last time'}</small></p>`).join('')}</div>`:''}<div class="study-plan-actions"><button class="primary" data-mode="focus">${started?'Practice my study plan':'Build my first study plan'} ${icon('arrow')}</button><span>Mistakes and hints shape your plan. It updates after every session.</span></div></section>`;
}
function graduationCard(){
  const course=courseStatus(bucket(),state.era),challenge=bucket().challenge,earned=challenge?.passedAt!=null;
  return `<section class="graduation-card ${earned?'badge-earned':''}" aria-label="Ground Zero graduation"><div class="graduation-pokemon">${sprite(149,'','')}${icon('trophy')}</div><div><span class="eyebrow">${earned?'TYPE HERO BADGE EARNED':'GROUND ZERO GRADUATE'}</span><h2>${earned?'You’ve earned your trainer stripes.':'Your foundation is complete!'}</h2><p>${course.completed.length} / ${course.available.length} chapters complete in ${ERAS[state.era].short}. ${earned?'Keep growing with focused practice and fresh challenges.':'Take on 20 mixed matchups. Get 16 correct without hints to earn your Type Hero badge.'}</p>${challenge?`<span class="challenge-history">Best: ${challenge.bestCorrect} / 20 · ${challenge.attempts} ${challenge.attempts===1?'attempt':'attempts'}</span>`:''}</div><button class="primary" data-mode="challenge">${earned?'Retake the challenge':'Take the Type Hero challenge'} ${icon('arrow')}</button></section>`;
}
function graduationView(){
  const course=courseStatus(bucket(),state.era);
  if(!course.graduated){lessonId=course.next.id;return learn();}
  return `${heading('YOU BUILT THE FOUNDATION','Ready for your next evolution?','Ground Zero is complete. Put your instincts together and take the next step.',`<button class="secondary" data-action="lessons">${icon('book')} Revisit lessons</button>`)}${graduationCard()}<section class="challenge-prep"><h3>Your Type Hero challenge</h3><div class="challenge-prep-grid"><div>${icon('swords')}<b>20 mixed matchups</b><p>14 single-type questions, then 6 dual-type calculations.</p></div><div>${icon('trophy')}<b>16 correct earns your badge</b><p>80% correct, without hints. Your best score stays with this era.</p></div><div>${icon('heart')}<b>Your pace, your progress</b><p>No timer. Get feedback after every answer and try again whenever you like.</p></div></div><p class="small muted">Your badge celebrates the challenge. Full chart mastery still requires three unaided correct answers for each matchup.</p></section>${studyGuide()}`;
}
function challengeResult(passed){
  const c=bucket().challenge;
  return `<div class="challenge-result ${passed?'earned':''}">${icon(passed?'trophy':'heart')}<div><b>${passed?'Type Hero · '+ERAS[state.era].short:'16 / 20 earns your Type Hero badge'}</b><p>${passed?'A milestone worth celebrating. Keep practicing to master the whole chart.':'Your study plan can help with the matchups you missed.'}</p>${c?`<small>Best: ${c.bestCorrect} / 20 · ${c.attempts} ${c.attempts===1?'attempt':'attempts'}${!passed&&c.passedAt!==null?' · Previously earned badge kept':''}</small>`:''}</div></div>`;
}

function learn(){if(lessonId==='graduation')return graduationView();if(lessonId){const l=LESSONS.find(l=>l.id===lessonId);return `${heading('GROUND ZERO · GUIDED LESSON',l.title,l.description,`<button class="secondary" data-action="lessons">${icon('book')} All lessons</button>`)}<section class="lesson-panel">${typeCast(l.types,'lesson-cast')}<h2>A little understanding goes a long way.</h2><p class="lesson-text">${l.text}</p><div class="damage-guide">${[2,1,.5,0].map(n=>`<div class="damage-cell effect-${n===.5?'half':n}"><b>${multiplier(n)}</b><span>${LABELS[n]}</span></div>`).join('')}</div><div class="notice">${ERAS[state.era].description}</div><button class="primary" data-action="lesson-start">Try what you learned ${icon('arrow')}</button><p class="small muted">${lessonQuestions(l,state.era).length} questions · 75% correct without hints completes this lesson · Retake anytime</p></section>`;}
return `${heading('YOUR FIRST STEP TO CONFIDENT BATTLES','Ground Zero','Start with the basics. Add a few types at a time. You don’t need to know anything yet.')}<div class="notice">${icon('info')} Using ${ERAS[state.era].name}: ${ERAS[state.era].description}</div><div class="lesson-grid">${LESSONS.map((l,i)=>{const available=lessonQuestions(l,state.era).length>0,complete=bucket().lessons.includes(l.id);return `<button class="lesson-card ${complete?'completed':''}" data-lesson="${l.id}" ${available?'':'disabled'}><div class="card-top"><span class="lesson-number">${complete?icon('check'):String(i+1).padStart(2,'0')}</span><span class="pill">${complete?'COMPLETE':!available?'NOT IN THIS ERA':l.tag}</span></div>${typeCast(l.types.slice(0,3),'lesson-card-cast')}<h3>${l.title}</h3><p>${l.description}</p><div class="card-bottom"><span>${available?lessonQuestions(l,state.era).length+' guided questions':'Switch to Gen II–V or Gen VI+'}</span>${icon('arrow')}</div></button>`;}).join('')}</div>`;}
function practice(){if(session)return sessionView(); const s=stats(bucket(),state.era);return `${heading('A LITTLE PRACTICE. A LOT OF CONFIDENCE.','The practice arena','Choose your focus. Every answer comes with an explanation, and every mistake helps shape your next practice.')}<div class="practice-banner">${sprite(6,'banner-pokemon','')}<div><h3>Your next battle is with yourself.</h3><p>No timers. No lost lives. Just one better instinct at a time.</p></div><span class="pill">${ERAS[state.era].short} RULES</span></div><div class="mode-grid">${modeCard('moves','bolt','Pick the move','Choose a verified move with the best type advantage.','8 BATTLES')}${modeCard('attack','swords','Attack matchups','You use a move. Predict the damage.','10 QUESTIONS')}${modeCard('defense','shield','Defend your Pokémon','Recognize incoming weaknesses and resistances.','10 QUESTIONS')}${modeCard('immunity','ghost','Immunity detective','Spot the attacks that fail—and the lookalikes that land.','MIXED MATCHUPS')}${modeCard('dual','grid','Double-type thinking','Multiply two types: 4×, ¼×, and everything between.','LEVEL UP')}${modeCard('review','clock','Your personal review','Revisit missed answers and matchups due for review.',`${s.due} READY`)}${modeCard('challenge','trophy','Type hero challenge','20 mixed questions. No hints. Earn your badge with 16 correct.','FINAL BOSS')}</div><div class="notice">${icon('info')} Practice covers all ${s.total} single-type matchups, including neutral results. New and missed matchups receive extra attention. Mastery needs three unaided correct answers and a recall after at least 12 hours.</div>`;}
function startSession(mode,lesson=null,custom=null){let questions=custom|| (lesson?lessonQuestions(lesson,state.era):mode==='moves'?buildMoveSession(state.era,bucket()):mode==='focus'?buildStudySession(state.era,bucket()):mode==='challenge'?[...buildSession('attack',state.era,bucket(),14),...buildSession('dual',state.era,bucket(),6)]:buildSession(mode,state.era,bucket())); if(!questions.length){toast(mode==='review'?'Nothing is due yet. Try matchup practice to build your review queue.':'This lesson is not available in this era.');return;}sounds.play('start');session={mode,lesson:lesson?.id,era:state.era,questions,index:0,answers:[],hint:false,answered:false};view='practice';location.hash='practice';render();window.scrollTo(0,0);}
function sessionView(){const x=session,finished=x.index>=x.questions.length;if(finished){const correct=x.answers.filter(a=>a.correct).length,unaided=x.answers.filter(a=>a.correct&&!a.assisted).length,passed=x.mode==='challenge'?unaided>=CHALLENGE_PASS:unaided/x.questions.length>=.75,l=x.lesson&&LESSONS.find(l=>l.id===x.lesson);return `${heading('ONE STEP STRONGER','Nice work, trainer.','Every answer is another connection made. Keep the useful ones close.')}<section class="result-panel"><div class="result-pokemon">${sprite(passed?149:buddy(),'','')}<span>${icon(passed?'trophy':'heart')}</span></div><h2>${x.mode==='challenge'?(passed?'Type Hero badge earned!':'Your next badge is within reach.'):(passed?'Your instincts are growing.':'Progress starts with showing up.')}</h2><p><b>${correct} / ${x.questions.length}</b> ${x.mode==='moves'?'best move choices':'correct · '+unaided+' without hints'}</p>${x.mode==='challenge'?challengeResult(passed):''}${l?`<div class="notice">${passed?'Lesson complete!':'This lesson needs 75% correct without hints. You can review the lesson and try again.'}</div>`:''}<div class="result-actions"><button class="primary" data-action="again">Practice again ${icon('arrow')}</button><button class="secondary" data-nav="progress">See my progress</button>${l?(courseStatus(bucket(),state.era).graduated?'<button class="secondary" data-action="graduation">Celebrate & take the challenge</button>':'<button class="secondary" data-action="next-lesson">Next lesson</button>'):''}<button class="secondary" data-mode="focus">Practice my tricky types</button></div><div class="answer-review">${x.questions.map((q,i)=>`<div class="review-row"><span class="answer-dot ${x.answers[i].correct?'good':'bad'}">${icon(x.answers[i].correct?'check':'close')}</span><span>${x.mode==='moves'?esc(q.moves[x.answers[i].moveIndex].move)+' · '+badge(q.moves[x.answers[i].moveIndex].type):badge(q.a)} ${icon('arrow')} ${q.ds.map(t=>badge(t)).join(' ')}</span><b>${multiplier(x.mode==='moves'?q.moves[x.answers[i].moveIndex].value:q.value)}</b><small>${x.mode==='moves'&&!x.answers[i].correct?'Best: '+q.moves.filter(m=>m.value===q.value).map(m=>m.move).join(' / ')+' ('+multiplier(q.value)+')':x.answers[i].assisted?'Hint used':x.answers[i].correct?'Got it':'Keep practicing'}</small></div>`).join('')}</div></section>`;}
if(x.mode==='moves')return moveBattleView();
const q=x.questions[x.index],move=moveExample(q.a,state.era),answer=x.answers[x.index],options=q.ds.length===2?[0,.25,.5,1,2,4]:[0,.5,1,2];return `<div class="session-header"><button class="text-button" data-action="exit">${icon('close')} Leave session</button><span class="pill">${x.lesson?'GROUND ZERO':x.mode==='challenge'?'TYPE HERO CHALLENGE':x.mode==='focus'?'YOUR STUDY PLAN':x.mode==='immunity'?'IMMUNITY DETECTIVE':x.mode.toUpperCase()+' PRACTICE'} · ${ERAS[state.era].short}</span><b>${x.index+1} <span class="muted">/ ${x.questions.length}</span></b></div><div class="progress-track session-track"><span style="width:${x.index/x.questions.length*100}%"></span></div><section class="battle-panel"><div class="eyebrow">${x.mode==='defense'?'SPOT THE INCOMING DAMAGE':x.mode==='immunity'?'IMMUNE OR JUST A LOOKALIKE?':'CALL THE MATCHUP'}</div><h1>${x.mode==='defense'?'How much damage does your Pokémon take?':'How effective is this attack?'}</h1><p>${move?`<strong>${esc(move.pokemonName)} used ${esc(move.move)}!</strong> `:''}A ${q.a}-type ${move?'attack':'chart example'} hits a ${q.ds.join(' / ')}-type ${x.mode==='defense'?'Pokémon on your team':'target'}.</p><div class="battle-scene ${x.answered?(answer.correct?'battle-success':'battle-miss'):''}"><span class="battle-scene-label">TYPE DOJO · TRAINING BATTLE</span><div class="battle-types"><div><span class="small eyebrow">ATTACKING POKÉMON</span>${battleActor([q.a],true)}<b class="battle-move-name">${move?esc(move.move):'Dragon chart practice'}</b>${badge(q.a,true)}</div><span class="battle-arrow">${icon('arrow')}<small>ATTACK</small></span><div><span class="small eyebrow">${x.mode==='defense'?'YOUR POKÉMON':'DEFENDING TARGET'}</span>${battleActor(q.ds)}<span class="battle-move-name battle-target-label">Defending types</span><div>${q.ds.map(t=>badge(t,true)).join(' ')}</div></div></div>${x.answered?`<span class="battle-result-stamp">${answer.correct?'Nice call!':'New matchup unlocked'}</span>`:''}</div>${moveInfo(move)}${mistakeReminder(q)}<div class="answer-options ${options.length===6?'six':''}">${options.map((n,i)=>`<button data-answer="${n}" data-effect="${n}" class="answer-option ${x.answered&&n===q.value?'correct':x.answered&&n===answer.value&&!answer.correct?'incorrect':''}" ${x.answered?'disabled':''}><span class="key">${i+1}</span><b>${multiplier(n)}</b><span>${LABELS[n]}</span></button>`).join('')}</div>${x.answered?`<div class="feedback ${answer.correct?'good':'bad'}" role="status"><b>${answer.correct?'You’ve got it!':'A useful one to remember.'} ${multiplier(q.value)} · ${LABELS[q.value]}</b><p>${!answer.correct?esc(mistakeExplanation(q,answer.value,state.era)):q.ds.map(d=>esc(mnemonic(q.a,d,state.era))).join(' ')}</p>${q.ds.length===2?`<div class="calculation">${q.ds.map(d=>`${q.a} → ${d}: ${multiplier(effectiveness(q.a,d,state.era))}`).join(' &nbsp; × &nbsp; ')} = <b>${multiplier(q.value)}</b></div>`:''}${answer.assisted?'<small>Hint used: this answer adds practice XP, but does not build a mastery streak.</small>':''}</div><button class="primary" data-action="next">${x.index+1===x.questions.length?'See your results':'Next matchup'} ${icon('arrow')}</button>`:x.hint?`<div class="hint-box">${icon('spark')}<p>${q.ds.map(d=>esc(mnemonic(q.a,d,state.era))).join(' ')}</p></div>`:`${x.mode!=='challenge'?'<button class="text-button hint-button" data-action="hint">'+icon('spark')+' Give me a memory hook</button>':''}<p class="small muted key-help">Use the number keys to answer. Enter advances after feedback.</p>`}</section>`;}

function mistakeReminder(q){
  const r=bucket().records[q.key],m=r?.lastMistake;
  if(!m||session?.answered||session?.mode==='challenge'||(r.streak!==0&&!r.moveMisses))return '';
  return '<div class="mistake-reminder">'+icon('spark')+'<span>'+ (m.kind==='move'?'A recent move-choice battle made this matchup tricky. Call its multiplier now.':'You previously chose '+multiplier(m.selected)+'. Check the attack direction'+(q.ds.length===2?' and both defending types':'')+' before answering.')+'</span></div>';
}
function submitMove(index){
  if(!session||session.mode!=='moves'||session.answered)return;
  const q=session.questions[session.index];if(!q?.moves[index])return;
  const answer=recordMoveChoice(bucket(),q,index);
  session.answers.push(answer);session.answered=true;
  sounds.playBattle(q.moves[index].type,answer.correct);save();render();
}
function moveBattleView(){
  const x=session,q=x.questions[x.index],answer=x.answers[x.index],partner=byId(q.pokemonId),selected=answer&&q.moves[answer.moveIndex],best=q.moves.filter(m=>m.value===q.value);
  return `<div class="session-header"><button class="text-button" data-action="exit">${icon('close')} Leave session</button><span class="pill">PICK THE MOVE · ${ERAS[state.era].short}</span><b>${x.index+1} / ${x.questions.length}</b></div>
    <div class="progress-track session-track"><span style="width:${x.index/x.questions.length*100}%"></span></div>
    <section class="battle-panel move-choice-panel"><div class="eyebrow">THINK LIKE A TRAINER</div><h1>Which move has the best type advantage?</h1><p>Choose a move for <strong>${partner.name}</strong>. Compare the type multiplier; power, STAB, stats, abilities, and special effects are set aside.</p>
    <div class="battle-scene ${x.answered?(answer.correct?'battle-success':'battle-miss'):''}"><span class="battle-scene-label">${esc(q.game)} · TRAINING BATTLE</span><div class="battle-types"><div><span class="small eyebrow">YOUR ATTACKER</span>${battleActor(pokemonTypes(partner,state.era),true,partner.id)}<b class="battle-move-name">${selected?esc(selected.move):'Choose your move'}</b><div>${selected?badge(selected.type,true):pokemonTypes(partner,state.era).map(t=>badge(t)).join(' ')}</div></div><span class="battle-arrow">${icon('arrow')}<small>ATTACK</small></span><div><span class="small eyebrow">DEFENDING TARGET</span>${battleActor(q.ds,false,q.targetId)}<span class="battle-move-name battle-target-label">Defending types</span><div>${q.ds.map(t=>badge(t,true)).join(' ')}</div></div></div></div>
    <div class="move-options">${q.moves.map((m,i)=>`<button class="move-option ${x.answered?(m.value===q.value?'correct':i===answer.moveIndex?'incorrect':''):''}" style="--move-type:${COLORS[m.type]}" data-move="${i}" ${x.answered?'disabled':''}><span class="key">${i+1}</span><b>${esc(m.move)}</b>${badge(m.type)}<span class="move-outcome">${x.answered?multiplier(m.value)+' · '+LABELS[m.value]:'Choose this move'}</span></button>`).join('')}</div>
    ${x.answered?`<div class="feedback ${answer.correct?'good':'bad'}" role="status"><b>${answer.correct?'Great choice!':'Here’s the stronger type advantage.'} ${best.map(m=>esc(m.move)).join(' or ')} · ${multiplier(q.value)}</b><p>${!answer.correct?esc(selected.move)+' gives '+multiplier(selected.value)+'. ':''}${q.ds.map(d=>esc(mnemonic(q.a,d,state.era))).join(' ')}</p>${q.ds.length===2?`<div class="calculation">${q.ds.map(d=>multiplier(effectiveness(q.a,d,state.era))).join(' × ')} = <b>${multiplier(q.value)}</b></div>`:''}<small>Any move tied for the highest multiplier counts as correct.</small></div>${q.moves.map(moveInfo).join('')}<button class="primary" data-action="next">${x.index+1===x.questions.length?'See your results':'Next battle'} ${icon('arrow')}</button>`:'<p class="small muted key-help">Use the number keys to choose a move. Every option is verified for this Pokémon in '+esc(q.game)+'.</p>'}</section>`;
}
function moveInfo(move){
  if(!move)return `<div class="move-exception">Generation I’s only Dragon move is Dragon Rage, which deals a fixed 40 HP. This question practices the Dragon chart rule rather than using Dragon Rage.</div>`;
  const how=move.method==='machine'?'by TM':move.method==='tutor'?'from a move tutor':`at Lv. ${move.level}`;
  return `<details class="move-info"><summary><span>${esc(move.pokemonName)} learns ${esc(move.move)} ${how}</span><span class="move-game">${esc(move.game)}</span>${icon('info')}</summary><div><p>This example is verified for ${esc(move.pokemonName)} itself in ${esc(move.game)}. Games in the same chart era can have different move lists; this example does not mean it is available in every game in the era.</p><p>Predict only the type multiplier. Level, power, stats, STAB, abilities, and secondary move effects are set aside for this exercise.</p><a href="${esc(move.pokemonSource)}" target="_blank" rel="noreferrer">Check this Pokémon’s learnset</a><span> · </span><a href="${esc(move.moveSource)}" target="_blank" rel="noreferrer">Check the move’s type</a></div></details>`;
}

function library(){const ts=typesFor(state.era);if(!ts.includes(libraryType))libraryType=ts[0];return `${heading('MAKE THE NUMBERS MEAN SOMETHING','The type library','Explore one type at a time. Learn what it beats, what beats it, and a memory hook for every special matchup.')}<div class="library-layout"><aside class="type-selector"><label class="search-field">${icon('search')}<input id="type-search" placeholder="Find a type…" value="${esc(librarySearch)}" aria-label="Search types"></label><div id="type-list">${typeList()}</div></aside><section id="type-detail">${typeDetail()}</section></div>`;}
function typeList(){return typesFor(state.era).filter(t=>t.toLowerCase().includes(librarySearch.toLowerCase())).map(t=>`<button class="type-select ${libraryType===t?'selected':''}" data-type="${t}" aria-pressed="${libraryType===t}">${orb(t)}<b>${t}</b>${icon('chevron')}</button>`).join('')||'<p class="empty small">No type matches that search.</p>';}
function typeDetail(){const t=libraryType,ts=typesFor(state.era);const categories=[['Strong against','attacking',2,'strong'],['Weak to','defending',2,'weak'],['Resisted by','attacking',.5,'resisted'],['Resists','defending',.5,'resists'],['No effect on','attacking',0,'immune'],['Immune to','defending',0,'immune']];return `${typeSpotlight(t)}<div class="type-title">${orb(t)}<div><span class="eyebrow">${ERAS[state.era].short} TYPE GUIDE</span><h2>${t}</h2></div><button class="secondary" data-action="type-practice">Practice ${t} ${icon('arrow')}</button></div><div class="type-groups">${categories.map(([title,dir,val,cls])=>{const targets=ts.filter(d=>effectiveness(dir==='attacking'?t:d,dir==='attacking'?d:t,state.era)===val);return `<div class="type-group"><div><h3>${title}</h3><span class="small muted">${dir==='attacking'?t+' attacks → opponent':'Incoming attacks → '+t} · ${multiplier(val)}</span></div><div>${targets.length?targets.map(d=>`<button class="badge-button" data-pair="${dir==='attacking'?t:d}>${dir==='attacking'?d:t}">${badge(d)}</button>`).join(''):'<span class="muted small">None</span>'}</div></div>`;}).join('')}</div><div class="section-heading"><h3>${icon('spark')} Memory hooks</h3><span class="small muted">Pictures to help game rules stick</span></div><div class="memory-hooks">${ts.filter(d=>effectiveness(t,d,state.era)!==1).map(d=>`<article class="hook"><div>${badge(t)}${icon('arrow')}${badge(d)}<b class="effect-tag">${multiplier(effectiveness(t,d,state.era))}</b></div><p>${esc(mnemonic(t,d,state.era))}</p></article>`).join('')}</div><p class="small muted">Memory hooks are imaginative cues, not scientific explanations. Always check the direction of the attack.</p>`;}
function chart(){const ts=typesFor(state.era);return `${heading('THE WHOLE PICTURE, ONE CELL AT A TIME','Matchup chart','Read across for your attacking move. Read down for the defending Pokémon. Select a cell for a memory hook.')}<div class="chart-legend">${[2,1,.5,0].map(n=>`<span><i class="effect-${n===.5?'half':n}">${multiplier(n)}</i>${LABELS[n]}</span>`).join('')}</div><div class="chart-wrap"><table class="type-chart"><caption>${ERAS[state.era].name} · Rows attack, columns defend</caption><thead><tr><th scope="col" class="corner">ATK ↓<br>DEF →</th>${ts.map(t=>`<th scope="col"><span class="column-type" style="color:${COLORS[t]}">${typeIcon(t)}<span>${t}</span></span></th>`).join('')}</tr></thead><tbody>${ts.map(a=>`<tr><th scope="row">${badge(a)}</th>${ts.map(d=>{const n=effectiveness(a,d,state.era);return `<td><button class="chart-cell effect-${n===.5?'half':n}" data-pair="${a}>${d}" aria-label="${a} attacks ${d}: ${multiplier(n)}, ${LABELS[n]}">${multiplier(n)}</button></td>`;}).join('')}</tr>`).join('')}</tbody></table></div><section class="calculator"><div><span class="eyebrow">TWO TYPES, ONE ANSWER</span><h3>Try a dual-type matchup</h3><p>Multiply both defending types. An immunity always makes the total zero.</p></div><div class="calculator-controls"><label>Attacking move<select id="calc-attack">${typeOptions(ts,'Rock')}</select></label><span>${icon('arrow')}</span><label>Defender type 1<select id="calc-one">${typeOptions(ts,'Fire')}</select></label><span>+</span><label>Defender type 2<select id="calc-two"><option value="">None</option>${typeOptions(ts,'Flying')}</select></label></div><div id="calc-result" aria-live="polite"></div></section><div class="notice">${ERAS[state.era].description}</div>`;}
const typeOptions=(ts,selected)=>ts.map(t=>`<option ${t===selected?'selected':''}>${t}</option>`).join('');
function calc(){const a=document.querySelector('#calc-attack')?.value,d=document.querySelector('#calc-one')?.value,e=document.querySelector('#calc-two')?.value;if(!a)return;const el=document.querySelector('#calc-result');if(d===e){el.innerHTML='<p class="muted">Choose two different types. A Pokémon cannot have the same type twice.</p>';return;}const value=dualEffectiveness(a,e?[d,e]:[d],state.era);el.innerHTML=`<b>${multiplier(value)} ${LABELS[value]}</b><span>${multiplier(effectiveness(a,d,state.era))}${e?' × '+multiplier(effectiveness(a,e,state.era)):''} = ${multiplier(value)}</span>`;}
function progress(){const s=stats(bucket(),state.era),entries=Object.keys(bucket().records).map(key=>{const [a,def]=key.split('>'),ds=def.split('+');return {a,ds,key,value:dualEffectiveness(a,ds,state.era)};}),filtered=entries.filter(p=>libraryFilter==='all'||libraryFilter==='mastered'&&mastered(bucket().records[p.key])||libraryFilter==='review'&&due(bucket().records[p.key])||libraryFilter==='learning'&&!mastered(bucket().records[p.key]));return `${heading('YOUR EFFORT, MADE VISIBLE','Look how far you’ve come.','Progress belongs to this game era. Switch generations to see that chart’s own learning history.',`<button class="primary" data-mode="review">Review my matchups ${icon('arrow')}</button>`)}<section class="metrics">${metric('Matchups mastered',`${s.mastered}<span> / ${s.total}</span>`,`${s.seen} explored · ${s.total-s.seen} still to discover`,'target')}${metric('Practice accuracy',s.attempted?`${s.accuracy}<span>%</span>`:'—',`${s.attempted} total answers`,'bolt')}${metric('Review queue',s.due,'Mistakes and spaced refreshers','clock')}${metric('Training XP',s.xp,'Correct: 10 · Hint: 4 · Mistake: 2','trophy')}</section><div class="battle-score"><b>Move-choice battles</b><span>${bucket().battles.correct} / ${bucket().battles.attempts} best choices</span><small>Battle decisions earn XP. Multiplier mastery is earned in matchup practice.</small></div><div class="progress-info"><h3>Understanding your progress</h3><p>A matchup is mastered after three consecutive correct answers without a hint, including a successful recall at least 12 hours after the previous answer once two are correct. Misses or hints reset the streak and recall requirement. Mastery earned before this update is kept. Reviews return after 1 minute, 10 minutes, 1 day, 3 days, then 7 days. Dual-type practice earns XP and has its own answer history; the mastery total counts the ${s.total} single-type cells.</p></div><div class="section-heading"><h2>Your matchup notebook</h2><label class="filter-label">Show<select id="progress-filter"><option value="all" ${libraryFilter==='all'?'selected':''}>All explored</option><option value="review" ${libraryFilter==='review'?'selected':''}>Ready for review</option><option value="learning" ${libraryFilter==='learning'?'selected':''}>Still learning</option><option value="mastered" ${libraryFilter==='mastered'?'selected':''}>Mastered</option></select></label></div>${filtered.length?`<div class="notebook"><table><thead><tr><th>Attacking move → Defender</th><th>Damage</th><th>Correct / Tried</th><th>Unaided streak</th><th>Status</th></tr></thead><tbody>${filtered.sort((a,b)=>Number(due(bucket().records[b.key]))-Number(due(bucket().records[a.key]))).map(p=>{const r=bucket().records[p.key];return `<tr><td><button class="pair-link" data-pair="${p.key}">${badge(p.a)}${icon('arrow')}${p.ds.map(t=>badge(t)).join(' ')}</button></td><td>${multiplier(p.value)}</td><td>${r.attempts?r.correct+' / '+r.attempts:'Battle retry'}</td><td>${r.streak} / 3${r.streak>=3&&!r.retained?'<small class="recall-note">Later recall needed</small>':''}</td><td><span class="status ${mastered(r)?'mastered':due(r)?'due':'learning'}">${mastered(r)?'Mastered':due(r)?'Review ready':'Learning'}</span></td></tr>`;}).join('')}</tbody></table></div>`:`<div class="empty-state">${sprite(133,'empty-pokemon','')}<h3>${s.seen?'No matchups in this view yet.':'A fresh notebook, a fresh start.'}</h3><p>${s.seen?'Try another filter or keep practicing.':'Your first practice session will fill this space with what you’ve learned.'}</p><button class="primary" data-mode="attack">Start practicing ${icon('arrow')}</button></div>`}<section class="backup-panel"><div><h3>Keep your adventure safe</h3><p>Your progress stays in this browser. Export a backup to move devices or keep a copy.</p></div><button class="secondary" data-action="export">${icon('download')} Export backup</button><button class="secondary" data-action="import">${icon('upload')} Import backup</button><button class="text-button danger" data-action="reset">Reset this era</button>${resetBackup?'<button class="text-button" data-action="undo-reset">Undo last reset</button>':''}<input type="file" id="backup-input" accept=".json,application/json" hidden></section>`;}
function render(){document.body.classList.toggle('sprites-paused',!animationEnabled());document.querySelector('#app').innerHTML=shell(({home,learn,practice,library,chart,progress})[view]());document.querySelectorAll('.nav-item').forEach(a=>a.setAttribute('aria-label',a.querySelector('span').textContent));if(view==='chart')calc();updateAdPlacement(view);document.title=`${({home:'Overview',learn:'Ground Zero',practice:'Practice arena',library:'Type library',chart:'Matchup chart',progress:'My progress'})[view]} · Type Dojo`;}
function dialog(title,body,actions=[{label:'Got it',value:true}],onDone=()=>{}){document.querySelector('dialog')?.remove();const d=document.createElement('dialog');d.className='modal';d.innerHTML=`<button class="modal-close text-button" aria-label="Close dialog">${icon('close')}</button><h2>${esc(title)}</h2><div class="modal-body">${body}</div><div class="modal-actions">${actions.map((a,i)=>`<button class="${i===actions.length-1?'primary':'secondary'}" data-dialog-index="${i}">${esc(a.label)}</button>`).join('')}</div>`;document.body.append(d);d.showModal();d.addEventListener('click',e=>{const b=e.target.closest('[data-dialog-index]');if(b){const value=actions[Number(b.dataset.dialogIndex)].value;d.close();onDone(value,d);}else if(e.target.closest('.modal-close'))d.close();});d.addEventListener('close',()=>d.remove());}

function soundSettings(){
  dialog('A little sound, a little magic',`<p>Soft, original chimes plus tiny splashes, crackles, and sparks when an attack resolves. No background music or hover sounds.</p><label class="sound-switch"><input id="sound-enabled" type="checkbox" ${settings.sound?'checked':''}> Enable gentle sounds</label><label class="sound-switch"><input id="battle-effects" type="checkbox" ${settings.battleEffects?'checked':''}> Elemental battle effects</label><label class="volume-label" for="sound-volume">Volume <output id="volume-value">${settings.volume}%</output></label><input id="sound-volume" type="range" min="0" max="100" step="5" value="${settings.volume}" aria-label="Sound volume"><div class="volume-hints"><span>Silent</span><span>Soft chimes</span></div><button class="secondary sound-preview" data-action="sound-preview" ${soundOn()?'':'disabled'}>${icon('volume')} Preview chime</button><button class="secondary sound-preview" data-action="effect-preview" ${soundOn()&&settings.battleEffects?'':'disabled'}>Preview Water splash</button><p id="sound-preview-status" class="small muted" role="status"></p><p class="small muted sound-note">Your mute and volume choices are saved on this device.</p>`);
}
function rememberReset(backup){
  resetBackup=backup;
  try{if(backup)localStorage.setItem('type-dojo-reset-backup-v1',JSON.stringify(backup));else localStorage.removeItem('type-dojo-reset-backup-v1');}catch{}
}
function performReset(scope){
  rememberReset(resetProgress(state,state.era,scope));
  session=null;lessonId=null;save();view='home';location.hash='home';render();window.scrollTo(0,0);
  toast(scope==='lessons'?'Ground Zero restarted. Your practice history and XP are kept.':'This era is ready for a fresh start. Undo last reset can restore it.');
}
function restartJourney(full=false){
  const eraName=ERAS[state.era].name;
  dialog('Restart your journey?',`<p>Choose what to restart for <b>${eraName}</b>. Your other game eras and study buddy stay as they are.</p><fieldset class="reset-options"><legend>What would you like to restart?</legend><label><input type="radio" name="reset-scope" value="lessons" ${full?'':'checked'}><span><b>Ground Zero lessons only</b><small>Clear completed chapters and return to the first lesson. Keep XP, mastery, practice answers, and reviews.</small></span></label><label><input type="radio" name="reset-scope" value="era" ${full?'checked':''}><span><b>All progress in this era</b><small>Clear lessons, XP, practice history, mastery, and training days for ${ERAS[state.era].short}.</small></span></label></fieldset><p class="small muted">An undo copy of your latest reset is saved on this device. You can also export a backup from My progress.</p>`,[{label:'Keep my journey',value:false},{label:'Restart selected progress',value:true}],(ok,d)=>{if(ok)performReset(d.querySelector('input[name="reset-scope"]:checked')?.value||'lessons');});
}
function undoReset(){
  if(!resetBackup)return;
  const backup=resetBackup;
  dialog('Restore your journey?',`<p>This restores ${backup.scope==='lessons'?'your completed Ground Zero chapters':'the progress from before your latest reset'} for <b>${ERAS[backup.era].name}</b>.</p><p>${backup.scope==='lessons'?'Practice answers and XP earned since the reset are kept.':'Any new progress in this era since the reset will be replaced by the saved copy.'}</p>`,[{label:'Keep current progress',value:false},{label:'Restore progress',value:true}],ok=>{if(ok){restoreProgress(state,backup);state.era=backup.era;rememberReset(null);session=null;lessonId=null;save();view='home';location.hash='home';render();toast('Your journey has been restored.');}});
}

function navigate(next){const go=()=>{if(next!==view){session=null;lessonId=null;}view=next;location.hash=next;render();window.scrollTo(0,0);};if(session&&session.index<session.questions.length&&next!==view){if(location.hash.slice(1)!==view)location.hash=view;dialog('Leave this practice session?','<p>Your answered questions are already saved. The remaining questions will be set aside.</p>',[{label:'Keep practicing',value:false},{label:'Leave session',value:true}],ok=>{if(ok)go();});}else go();}
function showPair(key){const [a,def]=key.split('>'),ds=def.split('+'),value=dualEffectiveness(a,ds,state.era);dialog(`${a} → ${ds.join(' / ')}`,`<div class="modal-matchup">${badge(a,true)}${icon('arrow')}${ds.map(d=>badge(d,true)).join(' ')}</div><div class="modal-damage">${multiplier(value)} <span>${LABELS[value]}</span></div><p>${ds.map(d=>esc(mnemonic(a,d,state.era))).join(' ')}</p><p class="small muted">${ERAS[state.era].name}. This is an attacking move hitting a defending type.</p>`);}
document.addEventListener('click',e=>{const chosen=e.target.closest('[data-buddy]');if(chosen){settings.buddy=Number(chosen.dataset.buddy);saveSettings();sounds.play('buddy');render();toast(`${buddy().name} joined your study team!`);return;}const nav=e.target.closest('[data-nav]');if(nav){e.preventDefault();navigate(nav.dataset.nav);return;}const mode=e.target.closest('[data-mode]');if(mode){startSession(mode.dataset.mode);return;}const lesson=e.target.closest('[data-lesson]');if(lesson){lessonId=lesson.dataset.lesson;view='learn';render();window.scrollTo(0,0);return;}const type=e.target.closest('[data-type]');if(type){libraryType=type.dataset.type;document.querySelector('#type-list').innerHTML=typeList();document.querySelector('#type-detail').innerHTML=typeDetail();return;}const pair=e.target.closest('[data-pair]');if(pair){showPair(pair.dataset.pair);return;}const moveChoice=e.target.closest('[data-move]');if(moveChoice){submitMove(Number(moveChoice.dataset.move));return;}const answer=e.target.closest('[data-answer]');if(answer){submit(Number(answer.dataset.answer));return;}const action=e.target.closest('[data-action]')?.dataset.action;if(!action)return;
if(action==='sound-toggle'){settings.sound=!soundOn();if(settings.sound&&settings.volume===0)settings.volume=25;sounds.configure({enabled:settings.sound,volume:settings.volume,battleEffects:settings.battleEffects});saveSettings();refreshSoundControl();if(settings.sound)sounds.play('tap');}
if(action==='sound-settings')soundSettings();
if(action==='effect-preview')sounds.playBattle('Water',true).then(played=>{const output=document.querySelector('#sound-preview-status');if(output)output.textContent=played?'Water effect played at your selected volume.':'Sound could not play. Try again with this tab open.';});
if(action==='sound-preview')sounds.play('correct').then(played=>{const output=document.querySelector('#sound-preview-status');if(output)output.textContent=played?'Preview played at your selected volume.':'Sound could not play. Try again with this tab open.';});
if(action==='restart-journey')restartJourney();
if(action==='undo-reset')undoReset();
if(action==='motion'){settings.motion=!settings.motion;saveSettings();render();toast(animationEnabled()?'Your Pokémon are ready to move!':'Sprites paused. Take your time, trainer.');}
if(action==='continue'||action==='graduation'){sounds.play('start');lessonId=courseStatus(bucket(),state.era).next?.id||'graduation';view='learn';location.hash='learn';render();window.scrollTo(0,0);}
if(action==='lessons'){lessonId=null;render();}
if(action==='lesson-start')startSession('lesson',LESSONS.find(l=>l.id===lessonId));
if(action==='hint'&&session&&!session.answered){session.hint=true;render();}
if(action==='next'&&session?.answered){session.index++;sounds.play(session.index===session.questions.length?(session.mode==='challenge'&&session.answers.filter(a=>a.correct&&!a.assisted).length>=CHALLENGE_PASS?'badge':'complete'):'tap');session.answered=false;session.hint=false;if(session.index===session.questions.length&&session.mode==='challenge'){recordChallenge(bucket(),session.answers.filter(a=>a.correct&&!a.assisted).length);save();}if(session.index===session.questions.length&&session.lesson){const success=session.answers.filter(a=>a.correct&&!a.assisted).length/session.questions.length>=.75;if(success&&!bucket().lessons.includes(session.lesson)){bucket().lessons.push(session.lesson);save();}}render();window.scrollTo(0,0);}
if(action==='exit')dialog('Leave this practice session?','<p>Your answers so far are saved. You can start a new session anytime.</p>',[{label:'Keep practicing',value:false},{label:'Leave session',value:true}],ok=>{if(ok){session=null;render();}});
if(action==='again'){const {mode,lesson}=session;startSession(mode,lesson?LESSONS.find(l=>l.id===lesson):null);}
if(action==='next-lesson'){const i=LESSONS.findIndex(l=>l.id===session.lesson),course=courseStatus(bucket(),state.era);lessonId=course.graduated?'graduation':LESSONS.slice(i+1).find(l=>lessonQuestions(l,state.era).length)?.id||course.next.id;session=null;view='learn';location.hash='learn';render();window.scrollTo(0,0);}
if(action==='type-practice'){const ts=typesFor(state.era),a=libraryType,qs=ts.map(d=>({a,ds:[d],key:matchupKey(a,[d]),value:effectiveness(a,d,state.era)}));startSession('attack',null,qs);}
if(action==='export'){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='type-dojo-progress.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Your progress backup has been exported.');}
if(action==='import')document.querySelector('#backup-input').click();
if(action==='reset')restartJourney(true);
if(action==='sources')dialog('Game rules & sources',`<p>This dojo teaches standard main-series attacking-type effectiveness: advantages, resistances, immunities, and dual-type multiplication.</p><p>Three chart eras cover the meaningful changes to the standard 18-type chart. Remakes follow their release era. Generation IX’s Stellar Tera type has special Terastallization rules and is not a normal nineteenth chart type.</p><p>Move examples are checked for the displayed species and the named game, using PokéAPI learnsets. Open the note beneath a training battle to see its learning method and source. Fixed-damage moves are not used as multiplier examples.</p><p>Abilities (such as Levitate), weather, STAB, stats, and battle transformations can modify actual damage. These lessons isolate the base type chart. Pokémon GO and the card game use different rules.</p><ul><li><a href="https://sg.portal-pokemon.com/game/type-chart/" target="_blank" rel="noreferrer">Official Pokémon type chart</a></li><li><a href="https://github.com/pret/pokered/blob/master/data/types/type_matchups.asm" target="_blank" rel="noreferrer">Original Red/Blue matchup data</a></li><li><a href="https://github.com/pret/pokecrystal/blob/master/data/types/type_matchups.asm" target="_blank" rel="noreferrer">Crystal matchup data</a></li><li><a href="https://bulbapedia.bulbagarden.net/wiki/Type/Type_chart" target="_blank" rel="noreferrer">Generation change reference</a></li></ul><p class="small muted">Sprites are bundled from <a href="https://github.com/PokeAPI/sprites" target="_blank" rel="noreferrer">PokéAPI’s sprite collection</a>. The pixel-art scenery is original to Type Dojo. Sprites share a consistent art style across eras; game rules and species typing follow your selected era. Pokémon images, names, and trademarks belong to their respective owners. See assets/ATTRIBUTION.md for credits.</p>`);
});
function submit(value){if(!session||session.mode==='moves'||session.answered||session.index>=session.questions.length)return;const q=session.questions[session.index],correct=value===q.value;sounds.playBattle(q.a,correct);session.answers.push({value,correct,assisted:session.hint});session.answered=true;recordAnswer(bucket(),q.key,correct,session.hint,Date.now(),{kind:'multiplier',selected:value});save();render();}
document.addEventListener('input',e=>{if(e.target.id==='sound-volume'){settings.volume=Number(e.target.value);sounds.configure({enabled:settings.sound,volume:settings.volume,battleEffects:settings.battleEffects});saveSettings();document.querySelector('#volume-value').textContent=settings.volume+'%';document.querySelectorAll('.sound-preview').forEach(b=>b.disabled=!soundOn()||(b.dataset.action==='effect-preview'&&!settings.battleEffects));refreshSoundControl();}if(e.target.id==='type-search'){librarySearch=e.target.value;document.querySelector('#type-list').innerHTML=typeList();}});
document.addEventListener('change',async e=>{if(e.target.id==='battle-effects'){settings.battleEffects=e.target.checked;sounds.configure({enabled:settings.sound,volume:settings.volume,battleEffects:settings.battleEffects});saveSettings();document.querySelector('[data-action="effect-preview"]').disabled=!soundOn()||!settings.battleEffects;}if(e.target.id==='sound-enabled'){settings.sound=e.target.checked;sounds.configure({enabled:settings.sound,volume:settings.volume,battleEffects:settings.battleEffects});saveSettings();document.querySelectorAll('.sound-preview').forEach(b=>b.disabled=!soundOn()||(b.dataset.action==='effect-preview'&&!settings.battleEffects));refreshSoundControl();}if(e.target.id==='era'){const era=e.target.value,change=()=>{state.era=era;session=null;lessonId=null;save();render();toast(`Now using ${ERAS[era].name}. Progress is tracked separately.`);};if(session&&session.index<session.questions.length){e.target.value=state.era;dialog('Switch game rules?',`<p>Your answered questions are saved. Switching eras ends this session and loads the selected era’s progress.</p>`,[{label:'Keep practicing',value:false},{label:'Switch era',value:true}],ok=>{if(ok)change();});}else change();}
if(e.target.id.startsWith('calc-'))calc();
if(e.target.id==='progress-filter'){libraryFilter=e.target.value;render();}
if(e.target.id==='backup-input'){const file=e.target.files[0];if(!file)return;try{if(file.size>2000000)throw new Error('Backup is too large.');const imported=validateState(JSON.parse(await file.text()));dialog('Restore this progress backup?','<p>This replaces the progress in all three eras with the backup’s history. Export your current progress first if you want to keep it.</p>',[{label:'Cancel',value:false},{label:'Restore backup',value:true}],ok=>{if(ok){state=imported;save();render();toast('Your progress has been restored.');}});}catch(err){toast('Could not import: '+err.message);}e.target.value='';}
});
document.addEventListener('keydown',e=>{if(document.querySelector('dialog')||['INPUT','SELECT','TEXTAREA'].includes(document.activeElement?.tagName))return;if(session&&view==='practice'&&session.index<session.questions.length){if(e.key==='Enter'&&session.answered&&document.activeElement?.tagName!=='BUTTON'){document.querySelector('[data-action="next"]').click();e.preventDefault();}else if(!session.answered&&/^[1-6]$/.test(e.key)){if(session.mode==='moves'){submitMove(Number(e.key)-1);return;}const options=session.questions[session.index].ds.length===2?[0,.25,.5,1,2,4]:[0,.5,1,2],n=options[Number(e.key)-1];if(n!==undefined)submit(n);}}});
window.addEventListener('hashchange',()=>{const next=location.hash.slice(1);if(['home','learn','practice','library','chart','progress'].includes(next)&&next!==view)navigate(next);});
document.addEventListener('visibilitychange',()=>{if(document.hidden)sounds.stop();else updateAdPlacement(view);});
window.addEventListener('pagehide',()=>sounds.stop());
window.addEventListener('storage',e=>{if(e.key===STORAGE_KEY&&e.newValue){try{state=validateState(JSON.parse(e.newValue));session=null;lessonId=null;render();toast('Progress updated in another tab.');}catch{}}if(e.key==='type-dojo-reset-backup-v1'){try{resetBackup=e.newValue?validateResetBackup(JSON.parse(e.newValue)):null;render();}catch{}}});
motionPreference.addEventListener('change',()=>render());
render();
